public interface OrderRepository extends JpaRepository<Order,Long>{@Modifying @Query("update Order o set o.deliveryPartner = null, o.updatedAt = CURRENT_TIMESTAMP where o.deliveryPartner.id = :id") int clearDeliveryPartner(@Param("id") Long id);Page<Order> findByCustomerId(Long id,Pageable p);Page<Order> findByDeliveryPartnerId(Long id,Pageable p);Page<Order> findByStatus(OrderStatus status,Pageable p);java.util.List<Order> findByDeliveryPartnerIsNullAndStatusInAndCreatedAtAfter(java.util.Collection<OrderStatus> statuses,Instant after);long countByStatus(OrderStatus s);long countByCreatedAtBetween(Instant a,Instant b);long countByStatusAndCreatedAtBetween(OrderStatus s,Instant a,Instant b);long countByDeliveryPartnerIdAndStatus(Long id,OrderStatus s);long countByDeliveryPartnerIdAndStatusAndDeliveredAtBetween(Long id,OrderStatus s,Instant a,Instant b);@Query("select o from Order o where (:status is null or o.status=:status) and (:q is null or cast(o.id as string) like concat('%',:q,'%') or lower(o.customer.name) like lower(concat('%',:q,'%')) or lower(o.customer.email) like lower(concat('%',:q,'%'))) and (:fromDate is null or o.createdAt>=:fromDate) and (:toDate is null or o.createdAt<:toDate)")Page<Order> adminSearch(@Param("q")String q,@Param("status")OrderStatus status,@Param("fromDate")Instant fromDate,@Param("toDate")Instant toDate,Pageable p);@Query("select o from Order o where o.deliveryPartner.id=:id and (:status is null or o.status=:status) and (:q is null or cast(o.id as string) like concat('%',:q,'%') or lower(o.customer.name) like lower(concat('%',:q,'%'))) and (:fromDate is null or o.createdAt>=:fromDate) and (:toDate is null or o.createdAt<:toDate)")Page<Order> partnerSearch(@Param("id")Long id,@Param("q")String q,@Param("status")OrderStatus status,@Param("fromDate")Instant fromDate,@Param("toDate")Instant toDate,Pageable p);@Query("select o from Order o left join o.deliveryPartner dp where ((dp.id=:id) or (dp is null and o.status in :openStatuses)) and (:q is null or cast(o.id as string) like concat('%',:q,'%') or lower(o.customer.name) like lower(concat('%',:q,'%'))) and (:status is null or o.status=:status) and (:fromDate is null or o.createdAt>=:fromDate) and (:toDate is null or o.createdAt<:toDate) order by o.createdAt desc") Page<Order> partnerSearchIncludingOpen(@Param("id")Long id,@Param("q")String q,@Param("status")OrderStatus status,@Param("fromDate")Instant fromDate,@Param("toDate")Instant toDate,@Param("openStatuses")java.util.Collection<OrderStatus> openStatuses,Pageable p);}
